  /**
     * Repeat the overdue notice every N days. 0 = send once only.
     * @minimum 0
     */
  overdueRepeatDays: number;
  /** Apply a late fee to overdue invoices. */
  lateFeeEnabled: boolean;
  /**
     * Late fee as a percentage of the invoice total.
     * @minimum 0
     */
